use crate::{state::Snapshot,AppState};use serde::{Deserialize,Serialize};use std::sync::atomic::Ordering::SeqCst;use std::time::Duration;use tauri::{AppHandle,Emitter,Manager,WebviewUrl,WebviewWindowBuilder};
const W:f64=300.0;const H:f64=56.0;
#[derive(Debug,Clone,Serialize,Deserialize)]pub struct PopupPayload{pub state:String,pub color:String,pub title:String,pub hint:String,pub action:Option<(String,String)>,pub ping:Option<u32>,pub seconds:u64}
pub fn position(app:&AppHandle)->(f64,f64){let st=app.state::<AppState>();let anchor=st.settings.read().anchor_tray;let(mw,mh)=app.primary_monitor().ok().flatten().map(|m|{let s=m.size().to_logical::<f64>(m.scale_factor());(s.width,s.height)}).unwrap_or((1280.0,720.0));if anchor{if let Some((x,y,w,h))=*st.tray_rect.lock(){let cx=(x+w/2.0-W/2.0).clamp(8.0,mw-W-8.0);let cy=if cfg!(target_os="macos"){y+h+6.0}else{y-H-8.0};return(cx,cy.clamp(8.0,mh-H-8.0));}}if cfg!(target_os="macos"){(mw-W-12.0,36.0)}else{(mw-W-12.0,mh-H-56.0)}}
pub fn show(app:&AppHandle,s:&Snapshot,seconds:u64){let payload=PopupPayload{state:s.state.name(),color:s.state.hex(),title:s.state.title().into(),hint:s.note.clone().unwrap_or_else(||s.state.hint().into()),action:s.state.action().map(|(a,b)|(a.into(),b.into())),ping:if s.state==crate::state::NetState::Online{s.international_ping}else{None},seconds};let st=app.state::<AppState>();*st.pending_popup.lock()=Some(payload.clone());st.popup_hold.store(false,SeqCst);let gen=st.popup_gen.fetch_add(1,SeqCst)+1;let win=match app.get_webview_window("popup"){Some(w)=>{let(x,y)=position(app);let _=w.set_position(tauri::LogicalPosition::new(x,y));w},None=>{let(x,y)=position(app);match WebviewWindowBuilder::new(app,"popup",WebviewUrl::App("popup.html".into())).title("NetWatch").decorations(false).transparent(true).always_on_top(true).skip_taskbar(true).resizable(false).focused(false).visible(false).inner_size(W,H).position(x,y).build(){Ok(w)=>w,Err(_)=>return}}};let app2=app.clone();tauri::async_runtime::spawn(async move{let _=win.emit("popup-data",&payload);let _=win.show();tokio::time::sleep(Duration::from_secs(seconds)).await;let started=std::time::Instant::now();loop{let st=app2.state::<AppState>();if st.popup_gen.load(SeqCst)!=gen||!st.popup_hold.load(SeqCst)||started.elapsed()>Duration::from_secs(30){break}tokio::time::sleep(Duration::from_millis(200)).await}let st=app2.state::<AppState>();if st.popup_gen.load(SeqCst)==gen{let _=win.close();}});}
pub fn open_dashboard(app:&AppHandle){if let Some(w)=app.get_webview_window("main"){let _=w.show();let _=w.unminimize();let _=w.set_focus();}}
